select p.productline, sum(od.quantityordered ) as total_terjual, round(avg(od.priceeach ), 2) as rerata_harga, round(avg(((p.msrp - od.priceeach) / p.msrp ) * 100), 2) as avg_discount_percentage from products p join orderdetails od on p.productcode = od.productcode group by p.productline having sum(od.quantityordered) > 3000 and round(avg(od.priceeach ), 2) > 80 order by total_terjual desc
